                type="text"
                placeholder={tx("Search candidates, job title, position, location...")}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-11 rounded-xl pl-10"
              />
            </div>

            <div className="w-full sm:w-64">
              <Select
                value={statusFilter}
                onValueChange={(val) => setStatusFilter(val ?? "ALL")}
              >
                <SelectTrigger className="h-11 w-full rounded-xl">
                  <SelectValue placeholder={tx("Application status")} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">{tx("All Statuses")}</SelectItem>
                  <SelectItem value="AI_INTERVIEW_PASSED">{tx("AI Interview Passed")}</SelectItem>
                  <SelectItem value="SHORTLISTED">{tx("Shortlisted")}</SelectItem>
                  <SelectItem value="HUMAN_INTERVIEW_SCHEDULED">{tx("Human Interview Scheduled")}</SelectItem>
                  <SelectItem value="UNDER_REVIEW">{tx("Under Review")}</SelectItem>
                  <SelectItem value="HIRED">{tx("Hired")}</SelectItem>
                  <SelectItem value="REJECTED">{tx("Rejected")}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="mt-3 flex items-center justify-between border-t border-border/60 pt-3 text-xs text-slate-500">
            <span>
              {tx("Showing ")}{filteredCandidates.length} {tx(" of ")}{forwardedApplications.length} {tx(" candidate(s)")}</span>
            {(search || statusFilter !== "ALL") && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => {
                  setSearch("");
                  setStatusFilter("ALL");
                }}
                className="h-7 text-xs text-slate-600"
              >
                {tx("Reset filters")}</Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Candidate List */}
      {filteredCandidates.length === 0 ? (
        <EmptyState
          title={tx("No forwarded candidates found")}
          description={tx(forwardedApplications.length === 0
              ? "Candidates who pass AI screening and moderator review will appear here."
              : "No candidates match your search filters.")}
        />
      ) : (
        <div className="grid gap-4">
          {filteredCandidates.map((item) => {
            const aiScore = item.aiResult?.feedback?.overallScore;
            const aiResult = item.aiResult?.feedback?.result;

            return (
              <Card
                key={item.application.id}
                className="group border border-border bg-surface shadow-sm transition-all hover:border-brand/40 hover:shadow-md"
              >
                <CardContent className="p-5 sm:p-6">
                  <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                    <div className="min-w-0 flex-1 space-y-2.5">
                      <div className="flex flex-wrap items-center gap-2.5">
                        <h3 className="text-lg font-semibold tracking-tight text-heading group-hover:text-brand">
                          {item.candidate.headline || tx("Candidate Profile")}
                        </h3>
                        <StatusPill>{item.application.status}</StatusPill>
                        {item.candidate.availabilityStatus && (
                          <span className="rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-medium text-slate-700 dark:bg-slate-800 dark:text-slate-300">
                            {item.candidate.availabilityStatus}
                          </span>
                        )}
                      </div>

                      {/* Position & Job Info */}
                      <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5 text-sm text-slate-700 dark:text-slate-300">
                        {item.candidate.currentPosition && (
                          <span className="flex items-center gap-1.5 font-medium">
                            <User className="size-4 text-slate-400" />
                            {item.candidate.currentPosition}
                          </span>
                        )}
                        <span className="flex items-center gap-1.5 text-brand font-medium">
                          <Briefcase className="size-4" />
                          {tx("Applied: ")}{item.application.jobTitle}
                        </span>
                      </div>

                      {/* AI Interview & Resume Highlights */}
                      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 pt-1 text-xs text-slate-500">
                        {item.candidate.preferredLocation && (
                          <span className="flex items-center gap-1">
                            <MapPin className="size-3.5 text-slate-400" />
                            {item.candidate.preferredLocation}
                          </span>
                        )}
                        {item.submittedResume?.title && (
                          <span className="flex items-center gap-1">
                            <FileText className="size-3.5 text-brand" />
                            {tx("Resume: ")}{item.submittedResume.title}
                          </span>
                        )}
                        {aiScore !== undefined && (
                          <span className="flex items-center gap-1 font-semibold text-emerald-600 dark:text-emerald-400">
                            <Sparkles className="size-3.5" />
                            {tx("AI Score: ")}{aiScore}/100 ({aiResult || tx("PASSED")})
                          </span>
                        )}
                        {item.forwardedAt && (
                          <span className="flex items-center gap-1 text-slate-400">
                            <Calendar className="size-3.5" />
                            {tx("Forwarded: ")}{new Date(item.forwardedAt).toLocaleDateString(undefined, { dateStyle: "medium" })}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="shrink-0 pt-2 sm:pt-0">
                      <Button
                        render={
                          <Link
                            href={`/recruiter/forwarded-candidates/${item.application.id}`}
                          />
                        }
                        variant="outline"
                        size="sm"
                        className="h-10 rounded-xl px-5 font-medium border-border hover:border-brand hover:text-brand"
                      >
                        {tx("View Full Details")}<ChevronRight className="ml-1.5 size-4" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";
import { useWorkspaceTranslation } from "@/i18n/useWorkspaceTranslation";


import { useState } from "react";
import Link from "next/link";
import {
  Briefcase,
  ChevronLeft,
  ChevronRight,
  DollarSign,
  Filter,
  MapPin,
  Search,
  UserCheck,
  UserRound,
} from "lucide-react";
import { PageIntro, StatusPill } from "@/components/shared/ApiCards";
import { EmptyState } from "@/components/shared/EmptyState";
import { ErrorState } from "@/components/shared/ErrorState";
import { LoadingState } from "@/components/shared/LoadingState";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useGetTalentQuery } from "@/services/recruiterApi";

export default function TalentDiscoveryPage() {
  const tx = useWorkspaceTranslation();
  const [keyword, setKeyword] = useState("");
  const [preferredLocation, setPreferredLocation] = useState("");
  const [availabilityStatus, setAvailabilityStatus] = useState<string>("ALL");
  const [page, setPage] = useState(0);

  const talentQuery = useGetTalentQuery({
    keyword: keyword.trim() || undefined,
    preferredLocation: preferredLocation.trim() || undefined,
    availabilityStatus: availabilityStatus !== "ALL" ? availabilityStatus : undefined,
    page,
    size: 10,
  });

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(0);
  };

  const clearFilters = () => {
    setKeyword("");
    setPreferredLocation("");
    setAvailabilityStatus("ALL");
    setPage(0);
  };

  const talentPage = talentQuery.data;
  const talents = talentPage?.content ?? [];
  const totalPages = talentPage?.totalPages ?? 0;

  return (
    <div className="space-y-6">
      <PageIntro
        eyebrow="GET /api/v1/recruiter/talent"
        title={tx("Talent Discovery")}
        description={tx("Explore published job-seeker profiles open for recruitment and candidate sourcing.")}
      />

      {/* Filter and Search Bar */}
      <Card className="border border-border bg-surface shadow-sm">
        <CardContent className="p-4 sm:p-6">
          <form onSubmit={handleSearchSubmit} className="space-y-4">
            <div className="grid gap-4 md:grid-cols-3">
              {/* Keyword Search */}
              <div className="relative">
                <Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
                <Input
                  type="text"
                  placeholder={tx("Search headline, skills, position...")}
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  className="h-11 rounded-xl pl-10"
                />
              </div>

              {/* Preferred Location */}
              <div className="relative">
                <MapPin className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
                <Input
                  type="text"
                  placeholder={tx("Location (e.g. Remote, HCMC)...")}
                  value={preferredLocation}
                  onChange={(e) => setPreferredLocation(e.target.value)}
                  className="h-11 rounded-xl pl-10"
                />
              </div>

              {/* Availability Filter */}
              <div>
                <Select
                  value={availabilityStatus}
                  onValueChange={(val) => {
                    setAvailabilityStatus(val ?? "ALL");
                    setPage(0);
                  }}
                >
                  <SelectTrigger className="h-11 w-full rounded-xl">
                    <SelectValue placeholder={tx("Availability status")} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ALL">{tx("All Availability Statuses")}</SelectItem>
                    <SelectItem value="Actively Looking">{tx("Actively Looking")}</SelectItem>
                    <SelectItem value="Open to Offers">{tx("Open to Offers")}</SelectItem>
                    <SelectItem value="Notice Period Required">{tx("Serving Notice Period")}</SelectItem>
                    <SelectItem value="Not Available">{tx("Not Available")}</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="flex items-center justify-between border-t border-border/60 pt-3">
              <span className="text-xs text-slate-500">
                {talentPage ? `${talentPage.totalElements} candidate(s) found` : tx("Searching candidates...")}
              </span>
              <div className="flex items-center gap-2">
                {(keyword || preferredLocation || availabilityStatus !== "ALL") && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={clearFilters}
                    className="h-9 rounded-lg text-slate-600"
                  >
                    {tx("Clear Filters")}</Button>
                )}
                <Button type="submit" size="sm" className="h-9 rounded-lg bg-brand px-5 text-white">
                  <Filter className="mr-1.5 size-3.5" />
                  {tx("Filter Candidates")}</Button>
              </div>
            </div>
          </form>
        </CardContent>
      </Card>

      {/* Talent List / States */}
      {talentQuery.isLoading ? (
        <LoadingState rows={6} />
      ) : talentQuery.isError ? (
        <ErrorState message={tx("Unable to load public candidate profiles. Please try again.")} />
      ) : talents.length === 0 ? (
        <EmptyState
          title={tx("No candidates match your criteria")}
          description={tx("Try broadening your search keywords or location filters.")}
        />
      ) : (
        <div className="grid gap-4">
          {talents.map((talent) => (
            <Card
              key={talent.profileId}
              className="group border border-border bg-surface shadow-sm transition-all hover:border-brand/40 hover:shadow-md"
            >
              <CardContent className="p-5 sm:p-6">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div className="space-y-2 min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="text-lg font-semibold tracking-tight text-heading group-hover:text-brand">
                        {talent.headline || tx("Published Candidate")}
                      </h3>
                      {talent.availabilityStatus && (
                        <StatusPill>{talent.availabilityStatus}</StatusPill>
                      )}
                    </div>

                    {talent.currentPosition && (
                      <p className="flex items-center gap-1.5 text-sm font-medium text-slate-700 dark:text-slate-300">
                        <Briefcase className="size-4 text-slate-400" />
                        {talent.currentPosition}
                      </p>
                    )}

                    <div className="flex flex-wrap gap-x-5 gap-y-1 text-xs text-slate-500 pt-1">
                      {talent.preferredLocation && (
                        <span className="flex items-center gap-1">
                          <MapPin className="size-3.5 text-brand" />
                          {talent.preferredLocation}
                        </span>
                      )}
                      {talent.expectedSalaryMin || talent.expectedSalaryMax ? (
                        <span className="flex items-center gap-1">
                          <DollarSign className="size-3.5 text-emerald-600" />
                          {formatSalaryRange(
                            talent.expectedSalaryMin,
                            talent.expectedSalaryMax,
                            talent.expectedSalaryCurrency
                          )}
                        </span>
                      ) : null}
                    </div>

                    {talent.bio && (
                      <p className="mt-2 line-clamp-2 text-xs leading-relaxed text-slate-600 dark:text-slate-400">
                        {talent.bio}
                      </p>
                    )}
                  </div>

                  <div className="shrink-0 pt-2 sm:pt-0">
                    <Button
                      render={<Link href={`/recruiter/talent/${talent.publicProfileSlug}`} />}
                      variant="outline"
                      size="sm"
                      className="h-10 rounded-xl px-5 font-medium border-border hover:border-brand hover:text-brand"
                    >
                      <UserRound className="mr-1.5 size-4" />
                      {tx("View Profile")}</Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}

          {/* Pagination Controls */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between pt-4">
              <p className="text-xs text-slate-500">
                {tx("Page ")}{page + 1} {tx(" of ")}{totalPages}
              </p>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page === 0}
                  onClick={() => setPage((p) => Math.max(0, p - 1))}
                  className="h-9 rounded-lg"
                >
                  <ChevronLeft className="mr-1 size-4" />
                  {tx("Previous")}</Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page >= totalPages - 1}
                  onClick={() => setPage((p) => p + 1)}
                  className="h-9 rounded-lg"
                >
                  {tx("Next")}<ChevronRight className="ml-1 size-4" />
                </Button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function formatSalaryRange(min?: number, max?: number, currency = "USD") {
  if (!min && !max) return null;
  const fmt = new Intl.NumberFormat();
  if (min && max) return `${currency} ${fmt.format(min)} - ${fmt.format(max)}`;
  if (min) return `From ${currency} ${fmt.format(min)}`;
  return `Up to ${currency} ${fmt.format(max!)}`;
}

"use client";
import { useWorkspaceTranslation } from "@/i18n/useWorkspaceTranslation";


import { useEffect } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { Save, RotateCcw, User, Briefcase, DollarSign, FileText } from "lucide-react";
import type { JobSeekerProfileResponse } from "@/contracts";
import { getApiErrorMessage } from "@/lib/api-error";
import {
  jobSeekerProfileSchema,
  type JobSeekerProfileFormValues,
} from "@/lib/validation/job-seeker.schema";
import { useUpdateJobSeekerProfileMutation } from "@/services/jobSeekerApi";
import { Button } from "@/components/ui/button";
import { Form } from "@/components/ui/form";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { SelectField, TextAreaField, TextField } from "@/components/shared/FormFields";

interface ProfileFormProps {
  profile: JobSeekerProfileResponse;
}

export function ProfileForm({ profile }: ProfileFormProps) {
  const tx = useWorkspaceTranslation();
  const [updateProfile, { isLoading }] = useUpdateJobSeekerProfileMutation();

  const getDefaultValues = (p: JobSeekerProfileResponse): JobSeekerProfileFormValues => ({
    headline: p.headline || "",
    bio: p.bio || "",
    currentPosition: p.currentPosition || "",
    expectedSalaryMin: p.expectedSalaryMin !== undefined && p.expectedSalaryMin !== null ? String(p.expectedSalaryMin) : "",
    expectedSalaryMax: p.expectedSalaryMax !== undefined && p.expectedSalaryMax !== null ? String(p.expectedSalaryMax) : "",
    expectedSalaryCurrency: p.expectedSalaryCurrency || "USD",
    salaryVisibility: p.salaryVisibility || "RECRUITERS_ONLY",
    preferredLocation: p.preferredLocation || "",
    availabilityStatus: p.availabilityStatus || "Actively Looking",
  });

  const form = useForm<JobSeekerProfileFormValues>({
    resolver: zodResolver(jobSeekerProfileSchema),
    defaultValues: getDefaultValues(profile),
  });

  useEffect(() => {
    form.reset(getDefaultValues(profile));
  }, [profile, form]);

  const onSubmit = async (values: JobSeekerProfileFormValues) => {
    try {
      const minSalary = values.expectedSalaryMin.trim() ? Number(values.expectedSalaryMin) : undefined;
      const maxSalary = values.expectedSalaryMax.trim() ? Number(values.expectedSalaryMax) : undefined;

      await updateProfile({
        headline: values.headline.trim() || undefined,
        bio: values.bio.trim() || undefined,
        currentPosition: values.currentPosition.trim() || undefined,
        expectedSalaryMin: minSalary,
        expectedSalaryMax: maxSalary,
        expectedSalaryCurrency: values.expectedSalaryCurrency.trim() || undefined,
        salaryVisibility: values.salaryVisibility,
        preferredLocation: values.preferredLocation.trim() || undefined,
        availabilityStatus: values.availabilityStatus.trim() || undefined,
      }).unwrap();

      toast.success(tx("Profile information updated successfully!"));
    } catch (error) {
      toast.error(getApiErrorMessage(error, tx("Unable to update profile.")));
    }
  };

  const handleReset = () => {
    form.reset(getDefaultValues(profile));
    toast.info(tx("Form reset to saved profile information."));
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        {/* Professional Summary & Overview */}
        <Card className="border border-border shadow-sm">
          <CardHeader className="bg-surface-muted/50 pb-4">
            <CardTitle className="flex items-center gap-2 text-lg font-semibold text-heading">
              <User className="size-5 text-brand" />
              {tx("General Profile Details")}</CardTitle>
          </CardHeader>
          <CardContent className="space-y-5 pt-6">
            <TextField
              control={form.control}
              name="headline"
              label={tx("Professional Headline")}
              placeholder={tx("e.g. Senior Full Stack Software Engineer | React & Node.js Specialist")}
              description={tx("A concise summary line displayed at the top of your profile.")}
            />

            <div className="grid gap-5 md:grid-cols-2">
              <TextField
                control={form.control}
                name="currentPosition"
                label={tx("Current Position")}
                placeholder={tx("e.g. Senior Frontend Engineer at TechCorp")}
              />
              <TextField
                control={form.control}
                name="preferredLocation"
                label={tx("Preferred Location")}
                placeholder={tx("e.g. Ho Chi Minh City, Remote, Relocation")}
              />
            </div>

            <div className="grid gap-5 md:grid-cols-2">
              <SelectField
                control={form.control}
                name="availabilityStatus"
                label={tx("Availability Status")}
                options={[
                  { value: "Actively Looking", label: "Actively Looking - Available Immediately" },
                  { value: "Open to Offers", label: "Open to Offers - Passive Job Seeking" },
                  { value: "Notice Period Required", label: "Serving Notice Period" },
                  { value: "Not Available", label: "Not Available Currently" },
                ]}
              />
            </div>

            <TextAreaField
              control={form.control}
              name="bio"
              label={tx("About You / Bio")}
              rows={5}
              placeholder={tx("Write a brief professional summary describing your key skills, background, achievements, and career goals...")}
              description={tx("Provide detailed background information for recruiters to learn more about you.")}
            />
          </CardContent>
        </Card>

        {/* Salary Expectations & Visibility */}
        <Card className="border border-border shadow-sm">
          <CardHeader className="bg-surface-muted/50 pb-4">
            <CardTitle className="flex items-center gap-2 text-lg font-semibold text-heading">
              <DollarSign className="size-5 text-brand" />
              {tx("Salary Expectations & Privacy")}</CardTitle>
          </CardHeader>
          <CardContent className="space-y-5 pt-6">
            <div className="grid gap-5 sm:grid-cols-3">
              <TextField
                control={form.control}
                name="expectedSalaryMin"
                label={tx("Minimum Expected Salary")}
                type="number"
                placeholder={tx("e.g. 2000")}
              />
              <TextField
                control={form.control}
                name="expectedSalaryMax"
                label={tx("Maximum Expected Salary")}
                type="number"
                placeholder={tx("e.g. 3500")}
              />
              <SelectField
                control={form.control}
                name="expectedSalaryCurrency"
                label={tx("Currency")}
                options={[
                  { value: "USD", label: "USD ($)" },
                  { value: "VND", label: "VND (₫)" },
                  { value: "EUR", label: "EUR (€)" },
                  { value: "SGD", label: "SGD ($)" },
                  { value: "GBP", label: "GBP (£)" },
                ]}
              />
            </div>

            <SelectField
              control={form.control}
              name="salaryVisibility"
              label={tx("Salary Privacy & Visibility")}
              description={tx("Control who can see your expected salary range.")}
              options={[
                { value: "PRIVATE", label: "Private - Only visible to you" },
                { value: "RECRUITERS_ONLY", label: "Recruiters Only - Visible to verified recruiters" },
                { value: "PUBLIC", label: "Public - Visible on your public profile" },
              ]}
            />
          </CardContent>
        </Card>

        {/* Action Buttons */}
        <div className="flex flex-wrap items-center justify-end gap-3 pt-2">
          <Button
            type="button"
            variant="outline"
            onClick={handleReset}
            disabled={isLoading || !form.formState.isDirty}
            className="h-11 rounded-xl px-6"
          >
            <RotateCcw className="mr-2 size-4" />
            {tx("Discard Changes")}</Button>
          <Button
            type="submit"
            disabled={isLoading}
            className="h-11 rounded-xl bg-brand px-8 font-medium hover:bg-brand/90 text-white shadow-sm"
          >
            <Save className="mr-2 size-4" />
            {isLoading ? tx("Saving Profile…") : tx("Save Profile Changes")}
          </Button>
        </div>
      </form>
    </Form>
  );
}
